package com.clavis.reader;
import android.app.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import java.util.zip.*;import org.json.*;
final class CatalogChecks {
 static int checks;static void check(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
 static GridLayout grid(View v){if(v instanceof GridLayout)return (GridLayout)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){GridLayout found=grid(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
 static View downloadIcon(View view){if(view instanceof ImageButton&&view.getContentDescription()!=null&&view.getContentDescription().toString().startsWith("Download "))return view;if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++){View found=downloadIcon(((ViewGroup)view).getChildAt(n));if(found!=null)return found;}return null;}
 static void zip(File file,String... names)throws Exception{try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(file))){for(String name:names){out.putNextEntry(new ZipEntry(name));out.write((name.endsWith(".mp3")?"ID3fixture":"fixture").getBytes(java.nio.charset.StandardCharsets.UTF_8));out.closeEntry();}}}
 static void erase(File file){if(file.isDirectory()){File[] children=file.listFiles();if(children!=null)for(File child:children)erase(child);}file.delete();}
 static String run(Instrumentation test)throws Exception{
  checks=0;Context c=test.getTargetContext();android.content.SharedPreferences region=c.getSharedPreferences("catalog_region",0);boolean had=region.contains("country");String previous=region.getString("country","");ArrayList<File> cleanup=new ArrayList<>();ArrayList<String> testUris=new ArrayList<>();final MainActivity[] opened={null};
  try{ArrayList<JSONObject> items=StarterCatalog.load(c);check(items.size()==125,"125 catalog records packaged");int ebooks=0,audio=0;HashSet<String> ids=new HashSet<>();for(JSONObject item:items){if(item.getString("kind").equals("EPUB"))ebooks++;else audio++;check(ids.add(item.getString("id")),"Unique catalog ID");check(item.getJSONArray("countries").length()>0,"Catalog rights evidence covers a download territory");check(item.getString("download").startsWith("https://"),"Catalog uses HTTPS downloads");check(!item.getString("rightsUrl").isEmpty()&&!item.getString("evidence").isEmpty(),"Rights and source evidence retained");}check(ebooks==25&&audio==100,"25 Gutenberg ebooks and 100 LibriVox recordings");
   for(JSONObject item:items)check(CatalogDownloads.downloadUri(item)!=null,"Every catalog download available without device-country lookup");
   boolean blocked=false;for(String url:new String[]{"https://unapproved.example/book.epub","http://www.gutenberg.org/book.epub","https://user@archive.org/book.zip"}){try{CatalogDownloads.downloadUri(new JSONObject(items.get(0).toString()).put("download",url));blocked=false;}catch(IOException expected){blocked=true;}check(blocked,"Unsafe download URL rejected");}
   ArrayList<JSONObject> page=CatalogRepository.ebooks("<feed xmlns='http://www.w3.org/2005/Atom'><entry><id>https://www.gutenberg.org/ebooks/74.opds</id><title>Tom &amp; friends</title><content>Twain</content></entry></feed>",25);check(page.size()==1&&page.get(0).getString("id").equals("pg-74")&&page.get(0).getInt("rank")==26,"OPDS pagination parses IDs and ranks");check(page.get(0).getString("title").equals("Tom & friends"),"Catalog XML entities decoded");
   CatalogRepository.State bounded=new CatalogRepository.State();for(int i=0;i<999;i++)bounded.items.add(new JSONObject().put("id","test-"+i));CatalogRepository.append(bounded,Arrays.asList(new JSONObject().put("id","test-0"),page.get(0),new JSONObject().put("id","overflow")));check(bounded.items.size()==1000&&!bounded.items.get(999).getString("id").equals("overflow"),"Catalog deduplicates and stops at 1000");
   JSONObject recordingMeta=new JSONObject().put("metadata",new JSONObject().put("identifier","fixture").put("title","Audio fixture").put("creator",new JSONArray().put("First").put("Second"))).put("files",new JSONArray().put(new JSONObject().put("name","track.mp3").put("format","VBR MP3").put("size",100)));JSONObject resolved=CatalogRepository.audio(recordingMeta,101);check(resolved.getString("download").endsWith("fixture_vbr_mp3.zip")&&resolved.getLong("bytes")==100,"Audio page selects playable VBR archive");check(CatalogRepository.artwork(page.get(0)).contains("pg74.cover.medium.jpg")&&CatalogRepository.artwork(resolved).equals("https://archive.org/services/img/fixture"),"Both catalog types use publisher cover URLs");
   File epub=File.createTempFile("catalog-check-",".epub",c.getCacheDir());cleanup.add(epub);zip(epub,"META-INF/container.xml");JSONObject ebook=new JSONObject(items.get(0).toString()).put("title","Catalog downloaded fixture");Book downloaded=CatalogDownloads.importFile(c,ebook,epub,new AtomicBoolean());cleanup.add(new File(epub.getParentFile(),epub.getName()+".rights.json"));check(downloaded.author.equals("EPUB"),"Completed EPUB import targets ebook shelf");check(new File(epub.getParentFile(),epub.getName()+".rights.json").isFile(),"Downloaded rights sidecar preserved");
   File audioZip=File.createTempFile("catalog-audio-check-",".zip",c.getCacheDir());cleanup.add(audioZip);zip(audioZip,"chapter10.mp3","chapter2.mp3");String unique="catalog-check-"+System.nanoTime();JSONObject recording=new JSONObject().put("id",unique).put("kind","Audio").put("title","Catalog audio fixture");File audioFolder=new File(c.getFilesDir(),"catalog-audio/"+unique);cleanup.add(audioFolder);Book audiobook=CatalogDownloads.importFile(c,recording,audioZip,new AtomicBoolean());check(audiobook.chapters.size()==2&&audiobook.chapters.get(0).title.contains("chapter2"),"Audio archive imports as one naturally ordered audiobook");check(new File(audioFolder,"source-rights.json").isFile(),"Recording source metadata retained");
   File bad=File.createTempFile("catalog-unsafe-check-",".zip",c.getCacheDir()),stage=new File(c.getCacheDir(),"catalog-stage-check-"+System.nanoTime());stage.mkdir();cleanup.add(bad);cleanup.add(stage);zip(bad,"../escape.mp3");blocked=false;try{CatalogDownloads.extract(bad,stage,new AtomicBoolean());}catch(IOException expected){blocked=true;}check(blocked,"Archive traversal rejected");
   Book imported=new Book(Uri.fromFile(new File(c.getCacheDir(),"catalog-import-check.epub")).toString(),"Imported ebook fixture","EPUB");imported.addedAt=1;downloaded.addedAt=2;ArrayList<Book> order=Store.newestFirst(Arrays.asList(downloaded,imported));check(order.get(0)==downloaded,"Newest additions first");imported.lastReadAt=3;check(Store.newestFirst(Arrays.asList(downloaded,imported)).get(0)==imported,"Recently opened item moves first");check(new Book(downloaded.json()).addedAt==2,"Added timestamp persists");
   synchronized(Store.class){ArrayList<Book> books=Store.load(c);books.add(downloaded);books.add(imported);books.add(audiobook);for(Book b:Arrays.asList(downloaded,imported,audiobook))testUris.add(b.uri);Store.save(c,books);}
   MainActivity a=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));opened[0]=a;for(String kind:new String[]{"EPUB","PDF","Audio"}){
    test.runOnMainSync(()->a.library(kind));test.waitForIdleSync();test.runOnMainSync(()->{TextView mine=FeedTabChecks.text(a.mainFrame,"My books"),browse=FeedTabChecks.text(a.mainFrame,"Browse");check(mine!=null&&browse!=null&&mine.isSelected(),"My books defaults first for "+kind);if(kind.equals("EPUB")){check(FeedTabChecks.text(a.mainFrame,"Imported ebook fixture")!=null,"Imported books appear in My books");check(FeedTabChecks.text(a.mainFrame,"Catalog downloaded fixture")!=null,"Downloaded books appear beside imports");}browse.performClick();});test.waitForIdleSync();test.runOnMainSync(()->{check(FeedTabChecks.text(a.mainFrame,"Browse").isSelected(),"Browse tab selected for "+kind);check(grid(a.mainFrame)!=null&&grid(a.mainFrame).getColumnCount()==2,"Browse uses a two-column cover grid");check(downloadIcon(a.mainFrame)!=null,"Right-side catalog download icon visible for "+kind);check(FeedTabChecks.text(a.mainFrame,"Source & rights")==null&&FeedTabChecks.text(a.mainFrame,"Download territory")==null,"Catalog cards omit source and territory buttons");FeedTabChecks.text(a.mainFrame,"My books").performClick();});test.waitForIdleSync();
   }
   test.runOnMainSync(()->UiStyle.library(a,"EPUB",true));test.waitForIdleSync();FeedPostChecks.snapshot(test,c,"catalog-ebooks");test.runOnMainSync(()->UiStyle.library(a,"Audio",true));test.waitForIdleSync();FeedPostChecks.snapshot(test,c,"catalog-audiobooks");test.runOnMainSync(a::finish);opened[0]=null;
  }finally{if(opened[0]!=null)test.runOnMainSync(opened[0]::finish);synchronized(Store.class){ArrayList<Book> books=Store.load(c);books.removeIf(b->testUris.contains(b.uri));Store.save(c,books);}if(had)region.edit().putString("country",previous).commit();else region.edit().remove("country").commit();for(File file:cleanup)erase(file);}
  if(test instanceof ReaderChecks&&((ReaderChecks)test).feedNetwork){CatalogRepository.State found=CatalogRepository.search(false,"blue castle",new CatalogRepository.State());check(!found.items.isEmpty(),"Online ebook search finds titles beyond initial snapshot");check(found.items.get(0).optString("title").toLowerCase(Locale.ROOT).contains("blue castle"),"Remote ebook result matches query");CatalogRepository.State recordings=CatalogRepository.search(true,"princess of mars",new CatalogRepository.State());check(!recordings.items.isEmpty(),"Online audiobook search finds titles beyond initial snapshot");check(recordings.items.get(0).optBoolean("pendingAudio"),"Audio search resolves media details only when requested");JSONObject details=CatalogRepository.audio(new JSONObject(CatalogRepository.get(recordings.items.get(0).getString("evidence"))),1);check(details!=null&&CatalogDownloads.downloadUri(details)!=null,"Online audiobook search result resolves a valid download");}
  return checks+" catalog, pagination, download, import and shelf checks passed";
 }
}



